static uint32_t _convert_shift_up_set(
    ztimer_convert_shift_t *ztimer_convert_shift, uint32_t val)
{
    uint32_t res = val;

    res >>= ztimer_convert_shift->shift;

    /* TODO: round up */

    return res;
}

static uint32_t _convert_shift_up_now(
    ztimer_convert_shift_t *ztimer_convert_shift, uint32_t val)
{
    uint32_t res = val;

    res <<= ztimer_convert_shift->shift;

