void ztimer_acquire(ztimer_clock_t *clock)
{
    unsigned state = irq_disable();

    if (clock->users++ == 0) {
        if (clock->ops->start) {
            clock->ops->start(clock);
        }
        else {
            clock->ops->set(clock, clock->max_value < UINT32_MAX ? (clock->max_value >> 1) : 0);
        }
    }

    irq_restore(state);
}

void ztimer_release(ztimer_clock_t *clock)
{
    unsigned state = irq_disable();

    assert(clock->users);
    if (--clock->users == 0) {
        clock->ops->cancel(clock);
        if (clock->ops->stop) {
            clock->ops->stop(clock);
        }
    }

    irq_restore(state);
}

bool ztimer_remove(ztimer_clock_t *clock, ztimer_t *timer)
{
    bool was_removed = false;
    unsigned state = irq_disable();

    if (_is_set(clock, timer)) {
        _ztimer_update_head_offset(clock);
        was_removed = _del_entry_from_list(clock, &timer->base);

        _ztimer_update(clock);
    }

    irq_restore(state);
    return was_removed;
}

